        if n.get('type')=='CallExpression': print('CALL path', ' > '.join(path[-8:]), n.get('loc'))
        if n.get('type')=='ScriptFunction': print('SCRIPT', n.get('id',{}).get('name'), 'path', ' > '.join(path[-7:]))
        if n.get('type')=='MethodDefinition': print('METHOD', n.get('key',{}).get('name'), 'static', n.get('static'), 'path', ' > '.join(path[-5:]))
